-- ONLY FOR EMPTY POKEAPP V2 DATABASE.
--
-- Generated operational bootstrap for Supabase SQL Editor.
-- Source of truth: supabase/v2/migrations/001_core.sql through 018_public_views_visibility.sql.
-- Do not edit this file manually; regenerate it with:
--   py tools/generate_supabase_v2_bootstrap.py
--
-- This file intentionally excludes the destructive development reset.
-- It contains no destructive reset statements and is not a reset script.

-- ============================================================================
-- BEGIN 001_core.sql
-- ============================================================================
-- PokeApp Supabase V2 greenfield schema.
-- 001_core: extensions, shared helpers, global trainers and seasons.
-- Intended for an empty Supabase/Postgres database, not for patching V1.

begin;

create extension if not exists pgcrypto;

create or replace function public.set_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

create table public.app_settings (
  key text primary key,
  value jsonb not null default '{}'::jsonb,
  description text not null default '',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint app_settings_key_format_chk
    check (key ~ '^[a-z0-9][a-z0-9_.:-]*$')
);

create trigger app_settings_set_updated_at
before update on public.app_settings
for each row execute function public.set_updated_at();

comment on table public.app_settings is
  'Small technical/global settings only. Never store league state, snapshots, Hall, trainer status or saves here.';

create table public.trainers (
  id uuid primary key default gen_random_uuid(),
  display_name text not null,
  slug text not null unique,
  auth_user_id uuid unique,
  globally_enabled boolean not null default true,
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint trainers_display_name_non_empty_chk
    check (length(btrim(display_name)) > 0),
  constraint trainers_slug_format_chk
    check (slug = lower(slug) and slug ~ '^[a-z0-9][a-z0-9_-]*$')
);

create trigger trainers_set_updated_at
before update on public.trainers
for each row execute function public.set_updated_at();

comment on table public.trainers is
  'Global trainer identity. Season status, robbed flags, points, coins and divisions live elsewhere.';
comment on column public.trainers.auth_user_id is
  'Prepared for Supabase Auth/RLS. No FK to auth.users in V2 SQL so local Postgres builds remain reproducible.';

create table public.seasons (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  status text not null default 'draft',
  created_by_trainer_id uuid references public.trainers(id) on delete set null,
  started_at timestamptz,
  finished_at timestamptz,
  archived_at timestamptz,
  discarded_at timestamptz,
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint seasons_name_non_empty_chk
    check (length(btrim(name)) > 0),
  constraint seasons_status_chk
    check (status in ('draft', 'active', 'finished', 'archived', 'discarded')),
  constraint seasons_lifecycle_timestamp_chk
    check (
      (status <> 'active' or started_at is not null)
      and (status <> 'finished' or finished_at is not null)
      and (status <> 'archived' or archived_at is not null)
      and (status <> 'discarded' or discarded_at is not null)
    )
);

create trigger seasons_set_updated_at
before update on public.seasons
for each row execute function public.set_updated_at();

comment on table public.seasons is
  'Real live/historical season. Archiving sets status=archived; relational data remains in place.';

commit;
-- ============================================================================
-- END 001_core.sql
-- ============================================================================

-- ============================================================================
-- BEGIN 002_seasons.sql
-- ============================================================================
-- PokeApp Supabase V2 greenfield schema.
-- 002_seasons: season participants, stats, config versions and divisions.

begin;

create table public.season_players (
  id uuid primary key default gen_random_uuid(),
  season_id uuid not null references public.seasons(id) on delete restrict,
  trainer_id uuid not null references public.trainers(id) on delete restrict,
  status text not null default 'active',
  seed_order integer,
  joined_at timestamptz not null default now(),
  left_at timestamptz,
  current_save_file_id uuid,
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint season_players_status_chk
    check (status in ('active', 'retired', 'abandoned', 'disqualified')),
  constraint season_players_seed_order_chk
    check (seed_order is null or seed_order > 0),
  constraint season_players_left_after_join_chk
    check (left_at is null or left_at >= joined_at),
  constraint uq_season_players_season_trainer
    unique (season_id, trainer_id),
  constraint uq_season_players_id_season
    unique (id, season_id),
  constraint uq_season_players_id_season_trainer
    unique (id, season_id, trainer_id)
);

create trigger season_players_set_updated_at
before update on public.season_players
for each row execute function public.set_updated_at();

comment on table public.season_players is
  'Trainer participation in a season. Current season status lives here, not on trainers.';
comment on column public.season_players.current_save_file_id is
  'Added as nullable now; the FK to save_files is added in 005_saves after save_files exists.';

create table public.season_player_stats (
  season_player_id uuid primary key,
  season_id uuid not null,
  trainer_id uuid not null,
  badges_count integer not null default 0,
  metadata jsonb not null default '{}'::jsonb,
  updated_at timestamptz not null default now(),
  constraint season_player_stats_badges_chk
    check (badges_count >= 0),
  constraint fk_season_player_stats_player
    foreign key (season_player_id, season_id, trainer_id)
    references public.season_players(id, season_id, trainer_id)
    on delete restrict
);

create trigger season_player_stats_set_updated_at
before update on public.season_player_stats
for each row execute function public.set_updated_at();

comment on table public.season_player_stats is
  'Season-scoped lightweight trainer stats such as badges. Coins are not stored here; they come from coin_transactions.';

create table public.trainer_flags (
  id uuid primary key default gen_random_uuid(),
  season_id uuid not null,
  trainer_id uuid not null,
  season_player_id uuid not null,
  flag_type text not null,
  flag_value boolean not null default true,
  payload jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint trainer_flags_type_chk
    check (flag_type = lower(flag_type) and flag_type ~ '^[a-z0-9_]+$'),
  constraint uq_trainer_flags_season_trainer_type
    unique (season_id, trainer_id, flag_type),
  constraint fk_trainer_flags_player_same_owner
    foreign key (season_player_id, season_id, trainer_id)
    references public.season_players(id, season_id, trainer_id)
    on delete restrict
);

create trigger trainer_flags_set_updated_at
before update on public.trainer_flags
for each row execute function public.set_updated_at();

comment on table public.trainer_flags is
  'Season-scoped trainer flags such as robbed. Competitive status remains in season_players.status.';

create table public.pokemon_flags (
  id uuid primary key default gen_random_uuid(),
  season_id uuid not null,
  trainer_id uuid not null,
  season_player_id uuid not null,
  fingerprint text not null,
  flag_type text not null,
  flag_value boolean not null default true,
  payload jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint pokemon_flags_fingerprint_chk
    check (length(btrim(fingerprint)) > 0),
  constraint pokemon_flags_type_chk
    check (flag_type = lower(flag_type) and flag_type ~ '^[a-z0-9_]+$'),
  constraint uq_pokemon_flags_season_owner_fingerprint_type
    unique (season_id, trainer_id, fingerprint, flag_type),
  constraint fk_pokemon_flags_player_same_owner
    foreign key (season_player_id, season_id, trainer_id)
    references public.season_players(id, season_id, trainer_id)
    on delete restrict
);

create trigger pokemon_flags_set_updated_at
before update on public.pokemon_flags
for each row execute function public.set_updated_at();

comment on table public.pokemon_flags is
  'Season-scoped Pokemon flags. Fingerprint is the stable Pokemon identity until the parser exposes a stronger id.';

create table public.season_config_versions (
  id uuid primary key default gen_random_uuid(),
  season_id uuid not null references public.seasons(id) on delete restrict,
  version_number integer not null,
  name text not null,
  effective_from_matchday integer not null,
  total_matchdays integer not null,
  division_count integer not null,
  promotion_relegation_count integer not null default 0,
  scoring_json jsonb not null default '{}'::jsonb,
  coin_rewards_json jsonb not null default '{}'::jsonb,
  rules_json jsonb not null default '{}'::jsonb,
  metadata jsonb not null default '{}'::jsonb,
  locked_at timestamptz,
  created_by_trainer_id uuid references public.trainers(id) on delete set null,
  created_at timestamptz not null default now(),
  constraint season_config_versions_number_chk
    check (version_number > 0),
  constraint season_config_versions_name_chk
    check (length(btrim(name)) > 0),
  constraint season_config_versions_effective_chk
    check (effective_from_matchday > 0),
  constraint season_config_versions_total_matchdays_chk
    check (total_matchdays > 0),
  constraint season_config_versions_division_count_chk
    check (division_count > 0),
  constraint season_config_versions_movement_chk
    check (promotion_relegation_count >= 0),
  constraint uq_season_config_versions_season_number
    unique (season_id, version_number),
  constraint uq_season_config_versions_season_effective
    unique (season_id, effective_from_matchday),
  constraint uq_season_config_versions_id_season
    unique (id, season_id)
);

comment on table public.season_config_versions is
  'Versioned season configuration. Used matchdays point to the exact config version so history is not reinterpreted.';

create table public.divisions (
  id uuid primary key default gen_random_uuid(),
  season_id uuid not null references public.seasons(id) on delete restrict,
  code text not null,
  name text not null,
  tier_order integer not null,
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  constraint divisions_code_chk
    check (code = upper(code) and code ~ '^[A-Z0-9_-]+$'),
  constraint divisions_name_chk
    check (length(btrim(name)) > 0),
  constraint divisions_tier_order_chk
    check (tier_order > 0),
  constraint uq_divisions_season_code
    unique (season_id, code),
  constraint uq_divisions_season_tier
    unique (season_id, tier_order),
  constraint uq_divisions_id_season
    unique (id, season_id)
);

comment on table public.divisions is
  'Season divisions. Supports A/B today and more tiers later without changing identity.';

commit;
-- ============================================================================
-- END 002_seasons.sql
-- ============================================================================

-- ============================================================================
-- BEGIN 003_league.sql
-- ============================================================================
-- PokeApp Supabase V2 greenfield schema.
-- 003_league: matchdays, matches, division history, snapshots and movements.

begin;

create table public.matchdays (
  id uuid primary key default gen_random_uuid(),
  season_id uuid not null references public.seasons(id) on delete restrict,
  number integer not null,
  status text not null default 'scheduled',
  season_config_version_id uuid not null,
  opened_at timestamptz,
  closed_at timestamptz,
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint matchdays_number_chk
    check (number > 0),
  constraint matchdays_status_chk
    check (status in ('scheduled', 'open', 'closed', 'cancelled')),
  constraint matchdays_closed_timestamp_chk
    check (status <> 'closed' or closed_at is not null),
  constraint uq_matchdays_season_number
    unique (season_id, number),
  constraint uq_matchdays_id_season
    unique (id, season_id),
  constraint fk_matchdays_config_same_season
    foreign key (season_config_version_id, season_id)
    references public.season_config_versions(id, season_id)
    on delete restrict
);

create trigger matchdays_set_updated_at
before update on public.matchdays
for each row execute function public.set_updated_at();

comment on table public.matchdays is
  'Official matchday/jornada. Closed matchdays keep their config version and snapshot.';

create table public.division_memberships (
  id uuid primary key default gen_random_uuid(),
  season_id uuid not null references public.seasons(id) on delete restrict,
  season_player_id uuid not null,
  division_id uuid not null,
  effective_from_matchday_number integer not null,
  effective_to_matchday_number integer,
  source_matchday_id uuid,
  reason text not null default 'initial',
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  constraint division_memberships_from_chk
    check (effective_from_matchday_number > 0),
  constraint division_memberships_to_chk
    check (
      effective_to_matchday_number is null
      or effective_to_matchday_number >= effective_from_matchday_number
    ),
  constraint division_memberships_reason_chk
    check (reason in ('initial', 'promotion', 'relegation', 'admin', 'status_change')),
  constraint uq_division_memberships_player_from
    unique (season_player_id, effective_from_matchday_number),
  constraint fk_division_memberships_player_same_season
    foreign key (season_player_id, season_id)
    references public.season_players(id, season_id)
    on delete restrict,
  constraint fk_division_memberships_division_same_season
    foreign key (division_id, season_id)
    references public.divisions(id, season_id)
    on delete restrict,
  constraint fk_division_memberships_source_matchday_same_season
    foreign key (source_matchday_id, season_id)
    references public.matchdays(id, season_id)
    on delete restrict
);

comment on table public.division_memberships is
  'Historical division membership. Do not overwrite current division in season_players and lose history.';

create table public.matches (
  id uuid primary key default gen_random_uuid(),
  season_id uuid not null,
  matchday_id uuid not null,
  division_id uuid not null,
  player_a_id uuid not null,
  player_b_id uuid not null,
  winner_id uuid,
  status text not null default 'scheduled',
  result_code text not null default '',
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint matches_status_chk
    check (status in ('scheduled', 'completed', 'forfeit', 'void')),
  constraint matches_players_different_chk
    check (player_a_id <> player_b_id),
  constraint matches_winner_is_player_chk
    check (winner_id is null or winner_id = player_a_id or winner_id = player_b_id),
  constraint uq_matches_matchday_pair
    unique (matchday_id, division_id, player_a_id, player_b_id),
  constraint fk_matches_matchday_same_season
    foreign key (matchday_id, season_id)
    references public.matchdays(id, season_id)
    on delete restrict,
  constraint fk_matches_division_same_season
    foreign key (division_id, season_id)
    references public.divisions(id, season_id)
    on delete restrict,
  constraint fk_matches_player_a_same_season
    foreign key (player_a_id, season_id)
    references public.season_players(id, season_id)
    on delete restrict,
  constraint fk_matches_player_b_same_season
    foreign key (player_b_id, season_id)
    references public.season_players(id, season_id)
    on delete restrict,
  constraint fk_matches_winner_same_season
    foreign key (winner_id, season_id)
    references public.season_players(id, season_id)
    on delete restrict
);

create trigger matches_set_updated_at
before update on public.matches
for each row execute function public.set_updated_at();

comment on table public.matches is
  'Actual league matches. Only stores data PokeApp uses: players, winner/status and metadata.';

create table public.matchday_snapshots (
  id uuid primary key default gen_random_uuid(),
  season_id uuid not null,
  matchday_id uuid not null,
  config_version_id uuid not null,
  revision integer not null default 1,
  snapshot_schema_version integer not null default 1,
  closed_at timestamptz not null,
  snapshot jsonb not null,
  created_by_trainer_id uuid references public.trainers(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint matchday_snapshots_revision_chk
    check (revision > 0),
  constraint matchday_snapshots_schema_version_chk
    check (snapshot_schema_version > 0),
  constraint uq_matchday_snapshots_matchday
    unique (matchday_id),
  constraint fk_matchday_snapshots_matchday_same_season
    foreign key (matchday_id, season_id)
    references public.matchdays(id, season_id)
    on delete restrict,
  constraint fk_matchday_snapshots_config_same_season
    foreign key (config_version_id, season_id)
    references public.season_config_versions(id, season_id)
    on delete restrict
);

create trigger matchday_snapshots_set_updated_at
before update on public.matchday_snapshots
for each row execute function public.set_updated_at();

comment on table public.matchday_snapshots is
  'One official closed snapshot per matchday. Admin recompute should update this row and increment revision explicitly.';

create table public.matchday_movements (
  id uuid primary key default gen_random_uuid(),
  season_id uuid not null,
  matchday_id uuid not null,
  season_player_id uuid not null,
  from_division_id uuid,
  to_division_id uuid,
  movement_type text not null,
  reason text not null default '',
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  constraint matchday_movements_type_chk
    check (movement_type in ('promotion', 'relegation', 'stay', 'admin')),
  constraint fk_matchday_movements_matchday_same_season
    foreign key (matchday_id, season_id)
    references public.matchdays(id, season_id)
    on delete restrict,
  constraint fk_matchday_movements_player_same_season
    foreign key (season_player_id, season_id)
    references public.season_players(id, season_id)
    on delete restrict,
  constraint fk_matchday_movements_from_division_same_season
    foreign key (from_division_id, season_id)
    references public.divisions(id, season_id)
    on delete restrict,
  constraint fk_matchday_movements_to_division_same_season
    foreign key (to_division_id, season_id)
    references public.divisions(id, season_id)
    on delete restrict
);

comment on table public.matchday_movements is
  'Official promotions/relegations/stays for queries and Discord/API summaries. Full closed state also remains in matchday_snapshots.';

commit;
-- ============================================================================
-- END 003_league.sql
-- ============================================================================

-- ============================================================================
-- BEGIN 004_shop.sql
-- ============================================================================
-- PokeApp Supabase V2 greenfield schema.
-- 004_shop: catalog, promotions, purchases, redemptions and coin ledger.

begin;

create table public.shop_items (
  id uuid primary key default gen_random_uuid(),
  code text not null unique,
  name text not null,
  category text not null,
  description text not null default '',
  base_price integer not null,
  enabled boolean not null default true,
  image_key text not null default '',
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint shop_items_code_chk
    check (code = lower(code) and code ~ '^[a-z0-9][a-z0-9_-]*$'),
  constraint shop_items_name_chk
    check (length(btrim(name)) > 0),
  constraint shop_items_category_chk
    check (category in ('comodines', 'bayas', 'competitivos', 'crianza', 'other')),
  constraint shop_items_base_price_chk
    check (base_price >= 0)
);

create trigger shop_items_set_updated_at
before update on public.shop_items
for each row execute function public.set_updated_at();

comment on table public.shop_items is
  'Version-controlled seedable shop catalog. Visible names are not foreign keys.';

create table public.shop_promotions (
  id uuid primary key default gen_random_uuid(),
  season_id uuid not null references public.seasons(id) on delete restrict,
  matchday_id uuid references public.matchdays(id) on delete restrict,
  shop_item_id uuid not null references public.shop_items(id) on delete restrict,
  promotion_type text not null,
  status text not null default 'pending',
  base_price integer not null,
  effective_price integer not null,
  stock_total integer not null,
  stock_used integer not null default 0,
  announced_at timestamptz,
  activates_at timestamptz,
  ends_at timestamptz,
  exhausted_at timestamptz,
  dedupe_key text,
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint shop_promotions_type_chk
    check (promotion_type in ('normal', 'mega')),
  constraint shop_promotions_status_chk
    check (status in ('pending', 'active', 'ended', 'exhausted', 'cancelled')),
  constraint shop_promotions_prices_chk
    check (base_price >= 0 and effective_price >= 0 and effective_price <= base_price),
  constraint shop_promotions_stock_chk
    check (stock_total >= 0 and stock_used >= 0 and stock_used <= stock_total),
  constraint uq_shop_promotions_id_season
    unique (id, season_id),
  constraint fk_shop_promotions_matchday_same_season
    foreign key (matchday_id, season_id)
    references public.matchdays(id, season_id)
    on delete restrict
);

create trigger shop_promotions_set_updated_at
before update on public.shop_promotions
for each row execute function public.set_updated_at();

comment on table public.shop_promotions is
  'Rotating discounts. Future API/RPC must claim stock atomically before inserting purchases.';

create table public.purchases (
  id uuid primary key default gen_random_uuid(),
  season_id uuid not null,
  trainer_id uuid not null,
  season_player_id uuid not null,
  shop_item_id uuid not null references public.shop_items(id) on delete restrict,
  promotion_id uuid,
  quantity integer not null default 1,
  unit_price integer not null,
  total_price integer generated always as (quantity * unit_price) stored,
  status text not null default 'pending',
  purchased_at timestamptz not null default now(),
  metadata jsonb not null default '{}'::jsonb,
  constraint purchases_quantity_chk
    check (quantity > 0),
  constraint purchases_unit_price_chk
    check (unit_price >= 0),
  constraint purchases_status_chk
    check (status in ('pending', 'used', 'cancelled', 'refunded')),
  constraint uq_purchases_id_season_trainer_item
    unique (id, season_id, trainer_id, shop_item_id),
  constraint fk_purchases_player_same_owner
    foreign key (season_player_id, season_id, trainer_id)
    references public.season_players(id, season_id, trainer_id)
    on delete restrict,
  constraint fk_purchases_promotion_same_season
    foreign key (promotion_id, season_id)
    references public.shop_promotions(id, season_id)
    on delete restrict
);

comment on table public.purchases is
  'Auditable single-item purchases. No purchase_lines until the product needs multi-item carts.';

create table public.redemptions (
  id uuid primary key default gen_random_uuid(),
  purchase_id uuid not null references public.purchases(id) on delete restrict,
  season_id uuid not null,
  trainer_id uuid not null,
  season_player_id uuid not null,
  shop_item_id uuid not null references public.shop_items(id) on delete restrict,
  redemption_type text not null default 'item_use',
  status text not null default 'applied',
  payload jsonb not null default '{}'::jsonb,
  redeemed_at timestamptz not null default now(),
  constraint redemptions_type_chk
    check (length(btrim(redemption_type)) > 0),
  constraint redemptions_status_chk
    check (status in ('applied', 'reverted', 'cancelled')),
  constraint fk_redemptions_purchase_same_owner_item
    foreign key (purchase_id, season_id, trainer_id, shop_item_id)
    references public.purchases(id, season_id, trainer_id, shop_item_id)
    on delete restrict,
  constraint fk_redemptions_player_same_owner
    foreign key (season_player_id, season_id, trainer_id)
    references public.season_players(id, season_id, trainer_id)
    on delete restrict
);

comment on table public.redemptions is
  'Purchase redemption/use audit. Purchase and redemption are intentionally separate.';

create table public.coin_transactions (
  id uuid primary key default gen_random_uuid(),
  season_id uuid not null,
  trainer_id uuid not null,
  season_player_id uuid not null,
  amount integer not null,
  transaction_type text not null,
  reference_type text not null default '',
  reference_id uuid,
  metadata jsonb not null default '{}'::jsonb,
  created_by_trainer_id uuid references public.trainers(id) on delete set null,
  created_at timestamptz not null default now(),
  constraint coin_transactions_amount_chk
    check (amount <> 0),
  constraint coin_transactions_type_chk
    check (transaction_type in ('matchday_reward', 'purchase', 'penalty', 'admin_adjustment', 'compensation')),
  constraint fk_coin_transactions_player_same_owner
    foreign key (season_player_id, season_id, trainer_id)
    references public.season_players(id, season_id, trainer_id)
    on delete restrict
);

comment on table public.coin_transactions is
  'Coin ledger. Balance is sum(amount); cached balances must be reconstructible from this table.';

commit;
-- ============================================================================
-- END 004_shop.sql
-- ============================================================================

-- ============================================================================
-- BEGIN 005_saves.sql
-- ============================================================================
-- PokeApp Supabase V2 greenfield schema.
-- 005_saves: raw save metadata, parsed save cache, current save and team locks.

begin;

create table public.save_files (
  id uuid primary key default gen_random_uuid(),
  season_id uuid not null references public.seasons(id) on delete restrict,
  trainer_id uuid not null references public.trainers(id) on delete restrict,
  storage_bucket text not null default 'raw-saves',
  storage_key text not null unique,
  original_filename text not null,
  sha256 text not null,
  parser_status text not null default 'pending',
  parser_version text not null default '',
  uploaded_at timestamptz not null default now(),
  deleted_at timestamptz,
  metadata jsonb not null default '{}'::jsonb,
  constraint save_files_storage_bucket_chk
    check (length(btrim(storage_bucket)) > 0),
  constraint save_files_storage_key_chk
    check (length(btrim(storage_key)) > 0),
  constraint save_files_original_filename_chk
    check (length(btrim(original_filename)) > 0),
  constraint save_files_sha256_chk
    check (sha256 ~ '^[a-f0-9]{64}$'),
  constraint save_files_parser_status_chk
    check (parser_status in ('pending', 'parsed', 'failed', 'stale')),
  constraint uq_save_files_id_season_trainer
    unique (id, season_id, trainer_id),
  constraint uq_save_files_trainer_season_sha
    unique (trainer_id, season_id, sha256)
);

comment on table public.save_files is
  'Raw save metadata only. Bytes live in a private storage bucket and paths must not be exposed publicly.';

create table public.parsed_saves (
  id uuid primary key default gen_random_uuid(),
  save_file_id uuid not null references public.save_files(id) on delete restrict,
  parser_version text not null,
  schema_version integer not null default 1,
  parsed_at timestamptz not null default now(),
  status text not null default 'parsed',
  payload jsonb not null,
  metadata jsonb not null default '{}'::jsonb,
  constraint parsed_saves_parser_version_chk
    check (length(btrim(parser_version)) > 0),
  constraint parsed_saves_schema_version_chk
    check (schema_version > 0),
  constraint parsed_saves_status_chk
    check (status in ('parsed', 'failed')),
  constraint uq_parsed_saves_file_parser
    unique (save_file_id, parser_version)
);

comment on table public.parsed_saves is
  'Parser payload/cache. Reparse with a new parser_version without mutating the raw save.';

alter table public.season_players
  add constraint fk_season_players_current_save_same_owner
  foreign key (current_save_file_id, season_id, trainer_id)
  references public.save_files(id, season_id, trainer_id)
  on delete restrict;

comment on column public.season_players.current_save_file_id is
  'Season-scoped current save. Replaces settings.current_save:* in V2.';

create table public.team_locks (
  id uuid primary key default gen_random_uuid(),
  season_id uuid not null,
  matchday_id uuid not null,
  trainer_id uuid not null,
  season_player_id uuid not null,
  save_file_id uuid not null,
  save_sha256 text not null,
  locked_at timestamptz not null default now(),
  deadline_at timestamptz,
  is_late boolean not null default false,
  public_team_snapshot jsonb not null,
  private_team_snapshot jsonb,
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint team_locks_save_sha256_chk
    check (save_sha256 ~ '^[a-f0-9]{64}$'),
  constraint team_locks_deadline_chk
    check (deadline_at is null or locked_at <= deadline_at or is_late = true),
  constraint uq_team_locks_matchday_trainer
    unique (matchday_id, trainer_id),
  constraint fk_team_locks_matchday_same_season
    foreign key (matchday_id, season_id)
    references public.matchdays(id, season_id)
    on delete restrict,
  constraint fk_team_locks_player_same_owner
    foreign key (season_player_id, season_id, trainer_id)
    references public.season_players(id, season_id, trainer_id)
    on delete restrict,
  constraint fk_team_locks_save_same_owner
    foreign key (save_file_id, season_id, trainer_id)
    references public.save_files(id, season_id, trainer_id)
    on delete restrict
);

create trigger team_locks_set_updated_at
before update on public.team_locks
for each row execute function public.set_updated_at();

comment on table public.team_locks is
  'Historical locked teams. Public snapshot is used for previews; private snapshot is owner/admin/server-only.';

commit;
-- ============================================================================
-- END 005_saves.sql
-- ============================================================================

-- ============================================================================
-- BEGIN 006_activity_hall.sql
-- ============================================================================
-- PokeApp Supabase V2 greenfield schema.
-- 006_activity_hall: append-only activity, Hall of Fame and archive snapshots.

begin;

create table public.activity_events (
  id uuid primary key default gen_random_uuid(),
  season_id uuid references public.seasons(id) on delete restrict,
  type text not null,
  actor_trainer_id uuid references public.trainers(id) on delete set null,
  trainer_id uuid references public.trainers(id) on delete set null,
  visibility text not null default 'public',
  dedupe_key text,
  context jsonb not null default '{}'::jsonb,
  payload jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  constraint activity_events_type_chk
    check (type = upper(type) and type ~ '^[A-Z0-9_]+$'),
  constraint activity_events_visibility_chk
    check (visibility in ('public', 'owner', 'admin', 'server_only'))
);

comment on table public.activity_events is
  'Append-only product facts. Notification views are derived and not stored.';

create table public.hall_of_fame_entries (
  id uuid primary key default gen_random_uuid(),
  season_id uuid not null references public.seasons(id) on delete restrict,
  competition_type text not null,
  champion_trainer_id uuid not null references public.trainers(id) on delete restrict,
  finalist_trainer_id uuid references public.trainers(id) on delete restrict,
  finalized_at timestamptz not null default now(),
  team_snapshot jsonb not null,
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  constraint hall_of_fame_entries_competition_type_chk
    check (competition_type in ('league', 'cup', 'tournament', 'doubles_cup')),
  constraint uq_hall_of_fame_season_competition
    unique (season_id, competition_type)
);

comment on table public.hall_of_fame_entries is
  'Immutable winner records. Champion team comes from a frozen snapshot, never from mutable current save.';

create table public.season_archive_snapshots (
  id uuid primary key default gen_random_uuid(),
  season_id uuid not null unique references public.seasons(id) on delete restrict,
  snapshot_schema_version integer not null default 1,
  snapshot jsonb not null,
  created_by_trainer_id uuid references public.trainers(id) on delete set null,
  created_at timestamptz not null default now(),
  constraint season_archive_snapshots_schema_version_chk
    check (snapshot_schema_version > 0)
);

comment on table public.season_archive_snapshots is
  'Optional final audit/export document. Relational season data remains authoritative and is not duplicated here.';

commit;
-- ============================================================================
-- END 006_activity_hall.sql
-- ============================================================================

-- ============================================================================
-- BEGIN 007_competitions.sql
-- ============================================================================
-- PokeApp Supabase V2 greenfield schema.
-- 007_competitions: generic cup tables, trials/cases and penalties.

begin;

create table public.cups (
  id uuid primary key default gen_random_uuid(),
  season_id uuid references public.seasons(id) on delete restrict,
  name text not null,
  competition_type text not null default 'cup',
  format text not null,
  status text not null default 'draft',
  started_at timestamptz,
  finished_at timestamptz,
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint cups_name_chk
    check (length(btrim(name)) > 0),
  constraint cups_competition_type_chk
    check (competition_type in ('cup', 'tournament', 'doubles_cup')),
  constraint cups_format_chk
    check (format in ('swiss', 'elimination', 'doubles', 'manual')),
  constraint cups_status_chk
    check (status in ('draft', 'active', 'finished', 'archived', 'discarded'))
);

create trigger cups_set_updated_at
before update on public.cups
for each row execute function public.set_updated_at();

comment on table public.cups is
  'Generic cup/tournament container. Swiss, elimination and doubles share one model through format.';

create table public.cup_participants (
  id uuid primary key default gen_random_uuid(),
  cup_id uuid not null references public.cups(id) on delete restrict,
  trainer_id uuid references public.trainers(id) on delete restrict,
  display_name text not null,
  seed_order integer,
  status text not null default 'active',
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  constraint cup_participants_display_name_chk
    check (length(btrim(display_name)) > 0),
  constraint cup_participants_seed_order_chk
    check (seed_order is null or seed_order > 0),
  constraint cup_participants_status_chk
    check (status in ('active', 'eliminated', 'dropped', 'disqualified'))
);

comment on table public.cup_participants is
  'Cup sides. For doubles/team cups, trainer_id can be null and metadata can carry member ids until product needs a richer team model.';

create table public.cup_matches (
  id uuid primary key default gen_random_uuid(),
  cup_id uuid not null references public.cups(id) on delete restrict,
  round_number integer not null,
  bracket_position integer,
  participant_a_id uuid references public.cup_participants(id) on delete restrict,
  participant_b_id uuid references public.cup_participants(id) on delete restrict,
  winner_participant_id uuid references public.cup_participants(id) on delete restrict,
  status text not null default 'scheduled',
  score text not null default '',
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint cup_matches_round_number_chk
    check (round_number > 0),
  constraint cup_matches_bracket_position_chk
    check (bracket_position is null or bracket_position > 0),
  constraint cup_matches_status_chk
    check (status in ('scheduled', 'completed', 'forfeit', 'bye', 'void')),
  constraint cup_matches_winner_is_side_chk
    check (
      winner_participant_id is null
      or winner_participant_id = participant_a_id
      or winner_participant_id = participant_b_id
    )
);

create trigger cup_matches_set_updated_at
before update on public.cup_matches
for each row execute function public.set_updated_at();

create table public.cup_standings (
  id uuid primary key default gen_random_uuid(),
  cup_id uuid not null references public.cups(id) on delete restrict,
  participant_id uuid not null references public.cup_participants(id) on delete restrict,
  position integer,
  points numeric(6, 2) not null default 0,
  wins integer not null default 0,
  losses integer not null default 0,
  metadata jsonb not null default '{}'::jsonb,
  updated_at timestamptz not null default now(),
  constraint cup_standings_position_chk
    check (position is null or position > 0),
  constraint cup_standings_record_chk
    check (wins >= 0 and losses >= 0),
  constraint uq_cup_standings_participant
    unique (cup_id, participant_id)
);

create trigger cup_standings_set_updated_at
before update on public.cup_standings
for each row execute function public.set_updated_at();

create table public.trial_cases (
  id uuid primary key default gen_random_uuid(),
  season_id uuid references public.seasons(id) on delete restrict,
  matchday_id uuid,
  accused_trainer_id uuid references public.trainers(id) on delete restrict,
  created_by_trainer_id uuid references public.trainers(id) on delete set null,
  title text not null,
  description text not null default '',
  status text not null default 'open',
  payload jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  resolved_at timestamptz,
  updated_at timestamptz not null default now(),
  constraint trial_cases_title_chk
    check (length(btrim(title)) > 0),
  constraint trial_cases_status_chk
    check (status in ('open', 'resolved', 'dismissed', 'cancelled')),
  constraint trial_cases_matchday_requires_season_chk
    check (matchday_id is null or season_id is not null),
  constraint fk_trial_cases_matchday_same_season
    foreign key (matchday_id, season_id)
    references public.matchdays(id, season_id)
    on delete restrict
);

create trigger trial_cases_set_updated_at
before update on public.trial_cases
for each row execute function public.set_updated_at();

create table public.trial_votes (
  id uuid primary key default gen_random_uuid(),
  trial_case_id uuid not null references public.trial_cases(id) on delete restrict,
  voter_trainer_id uuid not null references public.trainers(id) on delete restrict,
  vote text not null,
  payload jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  constraint trial_votes_vote_chk
    check (vote in ('guilty', 'not_guilty', 'abstain', 'other')),
  constraint uq_trial_votes_case_voter
    unique (trial_case_id, voter_trainer_id)
);

create table public.penalties (
  id uuid primary key default gen_random_uuid(),
  season_id uuid not null references public.seasons(id) on delete restrict,
  trainer_id uuid not null references public.trainers(id) on delete restrict,
  matchday_id uuid,
  trial_case_id uuid references public.trial_cases(id) on delete restrict,
  penalty_type text not null,
  amount integer not null default 0,
  payload jsonb not null default '{}'::jsonb,
  created_by_trainer_id uuid references public.trainers(id) on delete set null,
  created_at timestamptz not null default now(),
  resolved_at timestamptz,
  constraint penalties_type_chk
    check (length(btrim(penalty_type)) > 0),
  constraint fk_penalties_matchday_same_season
    foreign key (matchday_id, season_id)
    references public.matchdays(id, season_id)
    on delete restrict
);

comment on table public.penalties is
  'Official penalties from trials/admin. Effects can be matchday-scoped and are reflected in snapshots/ledger by application logic.';

commit;
-- ============================================================================
-- END 007_competitions.sql
-- ============================================================================

-- ============================================================================
-- BEGIN 008_indexes.sql
-- ============================================================================
-- PokeApp Supabase V2 greenfield schema.
-- 008_indexes: query indexes and uniqueness that depends on partial predicates.

begin;

create unique index uq_seasons_one_active
  on public.seasons ((status))
  where status = 'active';

create index idx_trainers_slug_enabled
  on public.trainers (slug)
  where globally_enabled = true;

create index idx_season_players_season_status
  on public.season_players (season_id, status, seed_order);

create index idx_season_config_versions_season_effective_desc
  on public.season_config_versions (season_id, effective_from_matchday desc);

create index idx_division_memberships_player_range
  on public.division_memberships (season_player_id, effective_from_matchday_number, effective_to_matchday_number);

create index idx_trainer_flags_season_type
  on public.trainer_flags (season_id, flag_type, trainer_id);

create index idx_pokemon_flags_owner_type
  on public.pokemon_flags (season_id, trainer_id, flag_type);

create index idx_matchdays_season_status
  on public.matchdays (season_id, status, number);

create index idx_matches_matchday_division
  on public.matches (matchday_id, division_id, status);

create index idx_matchday_movements_matchday
  on public.matchday_movements (matchday_id, movement_type);

create index idx_shop_items_category_enabled
  on public.shop_items (category, enabled, code);

create index idx_shop_promotions_season_matchday_status
  on public.shop_promotions (season_id, matchday_id, status, activates_at);

create unique index uq_shop_promotions_dedupe_key
  on public.shop_promotions (dedupe_key)
  where dedupe_key is not null and dedupe_key <> '';

create index idx_purchases_trainer_recent
  on public.purchases (trainer_id, purchased_at desc);

create index idx_purchases_season_item_status
  on public.purchases (season_id, shop_item_id, status);

create index idx_purchases_promotion
  on public.purchases (promotion_id)
  where promotion_id is not null;

create index idx_redemptions_purchase
  on public.redemptions (purchase_id, redeemed_at desc);

create index idx_coin_transactions_trainer
  on public.coin_transactions (season_id, trainer_id, created_at desc);

create index idx_save_files_trainer_recent
  on public.save_files (season_id, trainer_id, uploaded_at desc);

create index idx_save_files_sha256
  on public.save_files (sha256);

create index idx_parsed_saves_file_recent
  on public.parsed_saves (save_file_id, parsed_at desc);

create index idx_team_locks_matchday
  on public.team_locks (matchday_id, trainer_id);

create index idx_activity_events_recent
  on public.activity_events (created_at desc);

create index idx_activity_events_season_recent
  on public.activity_events (season_id, created_at desc);

create unique index uq_activity_events_dedupe_key
  on public.activity_events (dedupe_key)
  where dedupe_key is not null and dedupe_key <> '';

create index idx_hall_of_fame_champion
  on public.hall_of_fame_entries (champion_trainer_id, finalized_at desc);

create index idx_cups_season_status
  on public.cups (season_id, status, created_at desc);

create index idx_cup_matches_round
  on public.cup_matches (cup_id, round_number, bracket_position);

create index idx_trial_cases_season_status
  on public.trial_cases (season_id, status, created_at desc);

create index idx_penalties_trainer
  on public.penalties (season_id, trainer_id, created_at desc);

comment on index public.uq_seasons_one_active is
  'PokeApp runs one active league season at a time.';

commit;
-- ============================================================================
-- END 008_indexes.sql
-- ============================================================================

