using (voter_trainer_id = public.current_trainer_id() or public.is_current_user_admin())
with check (voter_trainer_id = public.current_trainer_id() or public.is_current_user_admin());

create policy penalties_owner_admin_read
on public.penalties
for select
using (trainer_id = public.current_trainer_id() or public.is_current_user_admin());

create policy penalties_admin_insert
on public.penalties
for insert
with check (public.is_current_user_admin());

create policy penalties_admin_update
on public.penalties
for update
using (public.is_current_user_admin())
with check (public.is_current_user_admin());

commit;
-- ============================================================================
-- END 011_rls_policies.sql
-- ============================================================================

-- ============================================================================
-- BEGIN 012_security_views.sql
-- ============================================================================
-- PokeApp Supabase V2 security layer.
-- 012_security_views: safe read projections for authenticated clients.

begin;

create or replace view public.public_trainers
with (security_invoker = true, security_barrier = true)
as
select
  id,
  display_name,
  slug,
  globally_enabled,
  created_at,
  updated_at
from public.trainers
where globally_enabled = true;

create or replace view public.current_trainer_profile
with (security_invoker = true, security_barrier = true)
as
select
  id,
  display_name,
  slug,
  auth_user_id,
  globally_enabled,
  is_admin,
  metadata,
  created_at,
  updated_at
from public.trainers
where id = public.current_trainer_id()
   or public.is_current_user_admin();

create or replace view public.public_seasons
with (security_invoker = true, security_barrier = true)
as
select
  id,
  name,
  status,
  started_at,
  finished_at,
  archived_at,
  discarded_at,
  created_at,
  updated_at
from public.seasons
where status <> 'discarded';

create or replace view public.public_season_players
with (security_invoker = true, security_barrier = true)
as
select
  id,
  season_id,
  trainer_id,
  status,
  seed_order,
  joined_at,
  left_at,
  created_at,
  updated_at
from public.season_players;

create or replace view public.public_season_player_stats
with (security_invoker = true, security_barrier = true)
as
select
  season_player_id,
  season_id,
  trainer_id,
  badges_count,
  updated_at
from public.season_player_stats;

create or replace view public.public_trainer_flags
with (security_invoker = true, security_barrier = true)
as
select
  id,
  season_id,
  trainer_id,
  season_player_id,
  flag_type,
  flag_value,
  created_at,
  updated_at
from public.trainer_flags
where flag_type = 'robbed'
  and flag_value = true;

create or replace view public.current_trainer_flags
with (security_invoker = true, security_barrier = true)
as
select *
from public.trainer_flags
where trainer_id = public.current_trainer_id()
   or public.is_current_user_admin();

create or replace view public.current_pokemon_flags
with (security_invoker = true, security_barrier = true)
